<?php
declare(strict_types=1);
namespace EPejabat\Modules\Training;
use EPejabat\Core\{Database,Core,Support,Authorization,Auth,Content,Signatories,Documents,Accounts};
final class ExtendedWeb {
 public function __construct(private \PDO $p,private ?array $user){}
 private function actor():int {if(!$this->user)Support::redirect('/login');return (int)$this->user['id'];}
 private static function e(mixed $v):string{return Support::escape($v);}
 private static function form(string $action,string $fields,bool $upload=false):string{return '<form method="post"'.($upload?' enctype="multipart/form-data"':'').'><input type="hidden" name="csrf" value="'.Support::csrf().'"><input type="hidden" name="action" value="'.$action.'">'.$fields.'<button>Hantar</button></form>';}
 private static function field(string $k,string $label,string $value='',string $type='text'):string{return '<label>'.self::e($label).'<input name="'.$k.'" type="'.$type.'" value="'.self::e($value).'" required></label>';}
 private static function inputTree(array $example,string $prefix='data'):string {$h='';foreach($example as $key=>$value){$name=$prefix.'['.$key.']';$label=ucwords(str_replace('_',' ',(string)$key));if(is_array($value))$h.='<fieldset><legend>'.self::e($label).'</legend>'.self::inputTree($value,$name).'</fieldset>';elseif(in_array($key,['action','kind','classification','calculation','type'],true)){$options=match($key){'action'=>in_array($value,['CHECK_IN','CHECK_OUT','CHECKPOINT'],true)?['CHECK_IN','CHECK_OUT','CHECKPOINT']:['REVIEW','PREVIEW','APPROVE','PUBLISH','GENERATE','LOCK','VOID'],'kind'=>in_array($value,['LETTER','CERTIFICATE'],true)?['LETTER','CERTIFICATE']:['COURSE','SPEAKER','PRE_TEST','POST_TEST','QUIZ'],'classification'=>['NONE','GENERIC','FUNCTIONAL'],'calculation'=>['FIXED','PER_HOUR','PER_DAY'],'type'=>in_array($value,['TEXT','RATING','CHOICE'],true)?['TEXT','RATING','CHOICE']:['BANNER','ACTIVITY','GALLERY','ANNOUNCEMENT']};$h.='<label>'.self::e($label).'<select name="'.$name.'">';foreach($options as $opt)$h.='<option value="'.$opt.'"'.($opt===$value?' selected':'').'>'.$opt.'</option>';$h.='</select></label>';}elseif(is_bool($value))$h.='<label>'.self::e($label).'<select name="'.$name.'"><option value="0">Tidak</option><option value="1">Ya</option></select></label>';elseif(in_array($key,['body','reason','notes','official_reference','label'],true))$h.='<label>'.self::e($label).'<textarea name="'.$name.'" rows="3" required>'.self::e($value).'</textarea></label>';else $h.='<label>'.self::e($label).'<input name="'.$name.'" value="'.self::e($value).'"'.(is_numeric($value)?' type="number" step="any"':'').' required></label>'; }return $h;}
 private static function jsonForm(string $action,string $label,array $example,string $hidden=''):string {return '<details><summary>'.self::e($label).'</summary>'.self::form($action,$hidden.self::inputTree($example)).'</details>';}
 private static function table(array $rows):string {if(!$rows)return '<p>Tiada rekod.</p>';$html='<div class="table-wrap"><table><thead><tr>';foreach(array_keys($rows[0]) as $k)$html.='<th>'.self::e($k).'</th>';$html.='</tr></thead><tbody>';foreach($rows as $r){$html.='<tr>';foreach($r as $v)$html.='<td>'.self::e(is_array($v)?Workflow::json($v):($v??'')).'</td>';$html.='</tr>'; }return $html.'</tbody></table></div>';}
 private function page(string $h):never {if(isset($_SESSION['attendance_display'])){$q=$_SESSION['attendance_display'];$h.='<section class="card"><p>Attendance QR: '.self::e($q['url']).'</p>'.Qr::svg($q['url']).(isset($q['binding'])?'<p>Personal binding code: '.self::e($q['binding']).'</p>':'').'</section>';}Support::layout('Module 1 — Training', '<nav class="actions"><a href="/training/portal">Portal</a><a href="/training">Program</a><a href="/training/history">My Training / CPD / Documents</a><a href="/training/full-setup">Upgrade</a><a href="/dashboard">Shared Core</a></nav>'.$h);}
 public function handle(string $path):never {
  try{if($path==='/training/full-setup')$this->setup();if(!ExtendedMigrations::ready($this->p)){http_response_code(503);$this->page('<p>Setup T2–T6 diperlukan. T1 dan Shared Core dikekalkan.</p>');}
   if($path==='/training/verify')$this->page('<h2>Semak sijil</h2>'.self::table([Official::verify($this->p,Core::text($_GET['key']??'',32))]));
   if($path==='/training/portal')$this->portal();
   if($path==='/training/content-image'){$a=Content::asset($this->p,Core::id($_GET['id']??''),'training');header('Content-Type: '.$a['mime']);readfile($a['path']);exit;}
   if($path==='/training/scan'&&isset($_GET['token'])){$_SESSION['attendance_pending']=Core::text($_GET['token'],64);Support::redirect($this->user?'/training/scan':'/login');}
   $u=$this->actor();$message='';if($_SERVER['REQUEST_METHOD']==='POST'){Support::checkCsrf();$message=$this->action($u,Support::post('action',50));}
   if($path==='/training/history')$this->history($u,$message);
   if($path==='/training/scan')$this->scan($u,$message);
   if($path==='/training/evaluation')$this->evaluation($u,$message);
   if($path==='/training/export'){$pid=Core::id($_GET['id']??'');$format=Core::text($_GET['format']??'',10);$bytes=Reporting::export($this->p,$u,$pid,$format,array_intersect_key($_GET,array_flip(['year','role','organisation_id','facility_id','unit_id','profession_id','position_id','attendance'])));header('Content-Type: '.match($format){'PDF'=>'application/pdf','XLSX'=>'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',default=>'text/csv; charset=utf-8'});header('Content-Disposition: attachment; filename="training-'.$pid.'.'.strtolower($format).'"');echo $bytes;exit;}
   if($path==='/training/output-preview'){header('Content-Type: application/pdf');echo Official::preview($this->p,$u,Core::id($_GET['id']??''));exit;}
   if($path==='/training/workstation')$this->workstation($u,Core::id($_GET['id']??''),$message);
   http_response_code(404);$this->page('<p>Halaman tidak ditemui.</p>');
  }catch(\PDOException $e){http_response_code(500);$this->page('<p>Ralat sistem. Rujukan: '.self::e(Support::log($e)).'</p>');}catch(\RuntimeException|\InvalidArgumentException|\JsonException $e){if(http_response_code()<400)http_response_code(400);$this->page('<p class="error">'.self::e($e->getMessage()).'</p>');}
 }
 private function setup():never {$u=$this->actor();if(!Authorization::super($this->p,$u)){http_response_code(403);throw new \RuntimeException('Super Admin diperlukan.');}if($_SERVER['REQUEST_METHOD']==='POST')Support::checkCsrf();Support::redirect('/upgrade');}
 private function action(int $u,string $action):string {$p=$this->p;$pid=Core::id($_POST['programme_id']??null,true);$d=$_POST['data']??[];if(!is_array($d))throw new \RuntimeException('Input tidak sah.');
  switch($action){
  case 'session':$id=Attendance::session($p,$u,$pid,$d);return 'Session #'.$id;
  case 'checkpoint':return 'Checkpoint #'.Attendance::checkpoint($p,$u,Core::id($d['session_id']),$d['title'],$d['opens_at'],$d['closes_at']);
  case 'token':$token=Attendance::token($p,$u,Core::id($d['session_id']),$d['action'],(int)$d['ttl'],Core::id($d['checkpoint_id']??null,true));$_SESSION['attendance_display']=['token'=>$token,'url'=>Accounts::origin().'/training/scan?token='.$token];return 'QR dicipta. Guna URL dan QR pada halaman ini.';
  case 'personal':$_SESSION['attendance_binding']??=bin2hex(random_bytes(32));$a=Policy::actor($p,$u);$token=Attendance::token($p,$u,Core::id($d['session_id']),$d['action'],(int)$d['ttl'],Core::id($d['checkpoint_id']??null,true),(int)$a['staff_identity_id'],$_SESSION['attendance_binding']);$_SESSION['attendance_display']=['token'=>$token,'binding'=>$_SESSION['attendance_binding'],'url'=>Accounts::origin().'/training/scan?token='.$token];return 'Personal QR disediakan; binding code perlu officer untuk scan.';
  case 'scan':Attendance::scan($p,$u,Support::post('token',64),$_POST['binding']??null);unset($_SESSION['attendance_pending']);return 'Attendance direkod.';
  case 'manual':return 'Event #'.Attendance::manual($p,$u,Core::id($d['session_id']),Core::id($d['registration_id']),$d['action'],$d['at'],$d['reason'],$d['notes'],Core::id($d['checkpoint_id']??null,true));
  case 'correction':return 'Correction #'.Attendance::correction($p,$u,Core::id($d['event_id']),$d['at'],$d['reason'],$d['notes']);
  case 'correction_review':Attendance::review($p,$u,Core::id($d['id']),in_array($d['approve']??false,[true,1,'1'],true));break;
  case 'cpd_rule':return 'CPD rule #'.Cpd::rule($p,$u,$pid,$d);
  case 'cpd_verify':Cpd::verifyRule($p,$u,Core::id($d['id']));break;
  case 'cpd_calculate':return 'CPD record #'.Cpd::calculate($p,$u,$pid,Core::id($d['registration_id']),Core::id($d['rule_id']));
  case 'cpd_override':return 'CPD record #'.Cpd::override($p,$u,$pid,Core::id($d['registration_id']),(float)$d['points'],$d['reason'],$d['reference']);
  case 'cpd_void':Cpd::void($p,$u,Core::id($d['id']),$d['reason']);break;
  case 'cpd_approve':Cpd::approve($p,$u,Core::id($d['id']));break;
  case 'evaluation_create':return 'Evaluation #'.Evaluation::create($p,$u,$pid,$d);
  case 'evaluation_publish':Evaluation::publish($p,$u,Core::id($d['id']));break;
  case 'evaluation_submit':Evaluation::submit($p,$u,Core::id($_POST['evaluation_id']),Core::id($_POST['registration_id']),$_POST['answers']??[]);return 'Evaluation disimpan.';
  case 'template':return 'Template #'.Official::template($p,$u,$pid,$d['kind'],$d['type'],$d['title'],$d['body']);
  case 'signatory':return 'Signatory #'.Signatories::create($p,$u,Core::id($d['organisation_id']),Core::id($d['user_id']),$d['name'],$d['position'],Core::id($d['document_id']),Core::id($d['version']));
  case 'output_draft':return 'Output #'.Official::draft($p,$u,$pid,Core::id($d['template_id']),Core::id($d['registration_id']??null,true),$d['role'],$d['reference'],$d['signatories'],Core::id($d['replaces_id']??null,true));
  case 'output_transition':Official::transition($p,$u,Core::id($d['id']),$d['action'],$d['reason']);break;
  case 'acknowledge':Official::acknowledge($p,$u,$pid,Core::id($d['registration_id']),in_array($d['attend']??false,[true,1,'1'],true),$d['reason']);break;
  case 'content':return 'Content #'.Content::create($p,$u,'training',Core::id($d['organisation_id']),$d);
  case 'content_publish':Content::publish($p,$u,Core::id($d['id']),in_array($d['published']??false,[true,1,'1'],true));break;
  default:throw new \RuntimeException('Action tidak sah.');}return 'Tindakan disimpan.';
 }
 private function portal():never {$h='<h2>Portal Latihan</h2><nav><a href="/training">Program</a> · Aktiviti · Galeri · Pengumuman · <a href="/login">Login</a></nav>'.'<form method="get" action="/training/verify"><label>Verification key<input name="key" required></label><button>Semak Sijil</button></form>';$h.='<div class="training-banners">';foreach(Content::publicRows($this->p,'training') as $r){$h.='<section class="card"><h3>'.self::e($r['type_key'].' — '.$r['title']).'</h3>';if($r['document_id'])$h.='<img class="public-image" src="/training/content-image?id='.$r['id'].'" alt="'.self::e($r['title']).'">';$h.='<p>'.nl2br(self::e($r['body'])).'</p>';if($r['cta_url'])$h.='<a href="'.self::e($r['cta_url']).'">Maklumat lanjut</a>';$h.='</section>';}$h.='</div><h2>Upcoming programmes</h2>';foreach(Database::query($this->p,'SELECT t.id FROM training_programmes t JOIN organisations o ON o.id=t.owner_organisation_id WHERE t.is_published=1 AND t.is_cancelled=0 AND o.is_active=1')->fetchAll() as $r){$c=Policy::config($this->p,Policy::programme($this->p,(int)$r['id']),true);if($c['end_at']>=gmdate('Y-m-d H:i:s'))$h.='<p><a href="/training/p?id='.$r['id'].'">'.self::e($c['title']).'</a></p>';}$totals=Database::query($this->p,"SELECT COUNT(*) FROM training_programmes t JOIN organisations o ON o.id=t.owner_organisation_id WHERE t.is_published=1 AND t.is_cancelled=0 AND o.is_active=1")->fetchColumn();$h.='<p>Program diterbitkan: '.(int)$totals.'</p>';$this->page($h);}
 private function history(int $u,string $message):never {
  $filters=array_intersect_key($_GET,array_flip(['year','type','role','organiser']));$rows=Reporting::mine($this->p,$u,$filters);$h='<h2>My Training / Professional Participation</h2><p>Mata CPD direkod portal; bukan pengesahan kredit MyCPD/regulator.</p><p>'.self::e($message).'</p><form method="get">';foreach(['year'=>'Tahun','type'=>'Jenis','role'=>'Role','organiser'=>'Penganjur'] as $k=>$label)$h.='<label>'.$label.'<input name="'.$k.'" value="'.self::e($filters[$k]??'').'"></label>';$h.='<button>Tapis</button></form>'; $portfolio=[];
  foreach($rows as $row){$h.='<section class="card"><h3>'.self::e($row['programme']).'</h3><p>'.self::e($row['year'].' · '.$row['type'].' · '.$row['organiser']).'</p><p>'.self::e($row['registration_status'].' · '.implode(', ',$row['roles'])).'</p><p>Organisasi semasa program: '.self::e($row['historical_profile']['organisation_name']).'</p>';foreach($row['roles'] as $role)$portfolio[$row['year'].' — '.$role]=($portfolio[$row['year'].' — '.$role]??0)+1;
   if($row['registration_status']==='CONFIRMED'){foreach(Database::query($this->p,'SELECT id,title FROM training_sessions WHERE programme_id=?',[$row['programme_id']])->fetchAll() as $session){$st=Attendance::status($this->p,$u,(int)$session['id'],(int)$row['registration']);$h.='<p>'.self::e($session['title'].' — '.$st['status'].' · '.$st['arrival'].' · '.$st['minutes'].' minit').'</p>';}foreach(Database::query($this->p,'SELECT id,title FROM training_evaluations WHERE programme_id=? AND published=1',[$row['programme_id']])->fetchAll() as $e)$h.='<p><a href="/training/evaluation?id='.$e['id'].'&registration_id='.$row['registration'].'">'.self::e($e['title']).'</a></p>';$h.=self::jsonForm('acknowledge','Sahkan hadir / tidak dapat hadir',['registration_id'=>$row['registration'],'attend'=>true,'reason'=>''],'<input type="hidden" name="programme_id" value="'.$row['programme_id'].'">');}
   foreach($row['cpd'] as $cp)$h.='<p>CPD: '.self::e($cp['points'].' · '.$cp['status']).'</p>';foreach($row['documents'] as $d){$h.='<p>'.self::e($d['kind'].' · '.$d['role_key'].' · '.$d['status']);if($d['status']==='LOCKED'&&$d['document_id'])$h.=' <a href="/download?id='.$d['document_id'].'&version=1">Download</a>';if($d['kind']==='CERTIFICATE')$h.=' <a href="/training/verify?key='.$d['verification_key'].'">Verify</a>';$h.='</p>';}$h.='</section>';
  }$h.='<h3>Portfolio role tahunan</h3>';foreach($portfolio as $label=>$total)$h.='<p>'.self::e($label).' — '.$total.'</p>';$this->page($h);
 }
 private function scan(int $u,string $message):never {if(isset($_GET['token'])){$_SESSION['attendance_pending']=Core::text($_GET['token'],64);Support::redirect('/training/scan');}$token=$_SESSION['attendance_pending']??'';$this->page(\EPejabat\Core\Ui::camera().'<h2>Attendance QR</h2><p>'.self::e($message).'</p>'.self::form('scan',self::field('token','Token',$token).'<label>Personal binding code (officer sahaja)<input name="binding"></label>').self::jsonForm('personal','Create my personal QR',['session_id'=>1,'action'=>'CHECK_IN','ttl'=>300]));}
 private function evaluation(int $u,string $message):never {$id=Core::id($_GET['id']??'');$reg=Core::id($_GET['registration_id']??'');$e=Evaluation::form($this->p,$u,$id,$reg);$h='<h2>'.self::e($e['title']).'</h2><p>'.self::e($message).'</p>';$fields='<input type="hidden" name="evaluation_id" value="'.$id.'"><input type="hidden" name="registration_id" value="'.$reg.'">';foreach($e['questions'] as $i=>$q){$fields.='<label>'.self::e($q['label']);if($q['type']==='TEXT')$fields.='<textarea name="answers['.$i.']" required></textarea>';else{$fields.='<select name="answers['.$i.']" required>';foreach($q['type']==='CHOICE'?$q['options']:array_combine(range($q['min'],$q['max']),range($q['min'],$q['max'])) as $key=>$label)$fields.='<option value="'.$key.'">'.self::e($label).'</option>';$fields.='</select>';}$fields.='</label>';}$this->page($h.self::form('evaluation_submit',$fields));}
 private function workstation(int $u,int $pid,string $message):never {
  $r=Policy::programme($this->p,$pid);$actions=['attendance.manage','attendance.view','cpd.manage','cpd.view','outputs.manage','evaluations.manage','reports.view','content.manage'];$permitted=false;foreach($actions as $a)if(Policy::allowed($this->p,$u,$a,$r))$permitted=true;if(!$permitted){http_response_code(403);throw new \RuntimeException('Workstation access denied.');}$hidden='<input type="hidden" name="programme_id" value="'.$pid.'">';$h='<h2>Programme Workstation #'.$pid.'</h2><p>'.self::e($message).'</p><p>Masa konfigurasi UTC. Polisi perlu diputuskan oleh admin; contoh bukan polisi rasmi.</p>';
  $forms=[
  'attendance.manage'=>[
   ['session','Create attendance session',['title'=>'Session','start_at'=>'YYYY-MM-DD HH:MM:SS','end_at'=>'YYYY-MM-DD HH:MM:SS','grace_minutes'=>0,'late_minutes'=>0,'too_late_minutes'=>0,'minimum_minutes'=>0,'early_minutes'=>0,'checkout_grace_minutes'=>0,'allow_late_completion'=>0,'allow_too_late_completion'=>0]],
   ['checkpoint','Create checkpoint',['session_id'=>1,'title'=>'Checkpoint','opens_at'=>'YYYY-MM-DD HH:MM:SS','closes_at'=>'YYYY-MM-DD HH:MM:SS']],['token','Create dynamic QR',['session_id'=>1,'action'=>'CHECK_IN','ttl'=>300]],['manual','Manual attendance',['session_id'=>1,'registration_id'=>1,'action'=>'CHECK_IN','at'=>'YYYY-MM-DD HH:MM:SS','reason'=>'','notes'=>'']],['correction','Request correction',['event_id'=>1,'at'=>'YYYY-MM-DD HH:MM:SS','reason'=>'','notes'=>'']]],
  'attendance.correct'=>[['correction_review','Review correction',['id'=>1,'approve'=>false]]],
  'cpd.manage'=>[['cpd_rule','Configure versioned CPD rule',['regulator_id'=>1,'profession_id'=>1,'category'=>'','classification'=>'NONE','official_reference'=>'','effective_from'=>'YYYY-MM-DD HH:MM:SS','effective_until'=>'YYYY-MM-DD HH:MM:SS','calculation'=>'FIXED','maximum'=>0,'allow_multi_role_sum'=>0,'roles'=>['participant'=>0]]],['cpd_calculate','Calculate CPD',['registration_id'=>1,'rule_id'=>1]],['cpd_override','Propose manual CPD',['registration_id'=>1,'points'=>0,'reason'=>'','reference'=>'']]],
  'cpd.approve'=>[['cpd_verify','Verify rule reference',['id'=>1]],['cpd_approve','Approve CPD',['id'=>1]],['cpd_void','Void CPD before correction',['id'=>1,'reason'=>'']]],
  'outputs.manage'=>[['template','Document template',['kind'=>'LETTER','type'=>'participant_letter','title'=>'','body'=>'{{name}} {{programme}} {{role}} {{reference}}']],['output_draft','Draft official document',['template_id'=>1,'registration_id'=>1,'role'=>'participant','reference'=>'','signatories'=>[1]]],['output_transition','Advance lifecycle',['id'=>1,'action'=>'REVIEW','reason'=>'']]],
  'outputs.approve'=>[['output_transition','Approve/void document',['id'=>1,'action'=>'APPROVE','reason'=>'']]],
  'signatories.manage'=>[['signatory','Authorised signatory (upload private JPEG first)',['organisation_id'=>$r['owner_organisation_id'],'user_id'=>1,'name'=>'','position'=>'','document_id'=>1,'version'=>1]]],
  'evaluations.manage'=>[['evaluation_create','Evaluation / quiz',['title'=>'','kind'=>'COURSE','questions'=>[['label'=>'','type'=>'TEXT','min'=>1,'max'=>5,'options'=>['Option A','Option B'],'answer'=>0]],'pass_percent'=>0,'required_for_certificate'=>0,'opens_at'=>'YYYY-MM-DD HH:MM:SS','closes_at'=>'YYYY-MM-DD HH:MM:SS']],['evaluation_publish','Publish evaluation',['id'=>1]]],
  'content.manage'=>[['content','Public content',['organisation_id'=>$r['owner_organisation_id'],'type'=>'ANNOUNCEMENT','title'=>'','body'=>'','starts_at'=>'YYYY-MM-DD HH:MM:SS','ends_at'=>'YYYY-MM-DD HH:MM:SS','sort_order'=>0]],['content_publish','Publish/unpublish content',['id'=>1,'published'=>false]]]];
  foreach($forms as $permission=>$list)if(Policy::allowed($this->p,$u,$permission,$r))foreach($list as [$a,$label,$example])$h.=self::jsonForm($a,$label,$example,$hidden);
  if(Policy::allowed($this->p,$u,'attendance.view',$r))$h.='<h3>Sessions</h3>'.self::table(Database::query($this->p,'SELECT id,title,start_at,end_at FROM training_sessions WHERE programme_id=?',[$pid])->fetchAll());
  if(Policy::allowed($this->p,$u,'outputs.manage',$r)){$h.='<h3>Templates</h3>'.self::table(Database::query($this->p,'SELECT id,kind,type_key,title FROM training_templates WHERE programme_id=?',[$pid])->fetchAll()).'<h3>Official outputs (Preview / download)</h3>';foreach(Database::query($this->p,'SELECT id,status,document_id FROM training_outputs WHERE programme_id=?',[$pid])->fetchAll() as $o)$h.='<p>#'.$o['id'].' '.self::e($o['status']).' <a href="/training/output-preview?id='.$o['id'].'">Preview</a>'.($o['document_id']?' <a href="/download?id='.$o['document_id'].'&version=1">Download</a>':'').'</p>';}
  if(Policy::allowed($this->p,$u,'cpd.view',$r))$h.='<h3>CPD (portal records, not regulator credit)</h3>'.self::table(Cpd::history($this->p,$u,$pid));
  if(Policy::allowed($this->p,$u,'reports.view',$r))$h.='<h3>Live summary</h3>'.self::table([Reporting::dashboard($this->p,$u,$pid)]).self::table(Reporting::rows($this->p,$u,$pid)).'<p><a href="/training/export?id='.$pid.'&format=CSV">CSV</a> · <a href="/training/export?id='.$pid.'&format=XLSX">Excel</a> · <a href="/training/export?id='.$pid.'&format=PDF">PDF / Print</a></p>';
  if(Policy::allowed($this->p,$u,'attendance.manage',$r)||Policy::allowed($this->p,$u,'outputs.manage',$r)||Policy::allowed($this->p,$u,'cpd.manage',$r)){$h.='<h3>Peserta program (rujukan)</h3>';foreach(Database::query($this->p,'SELECT id,snapshot_json FROM training_registrations WHERE programme_id=?',[$pid])->fetchAll() as $reg){$ss=json_decode($reg['snapshot_json'],true);$h.='<p>Registration #'.$reg['id'].' — '.self::e($ss['full_name'].' · '.$ss['organisation_name']).'</p>';}}
  if(Policy::allowed($this->p,$u,'attendance.manage',$r))$h.='<h3>Checkpoints</h3>'.self::table(Database::query($this->p,'SELECT c.id,c.session_id,c.title,c.opens_at,c.closes_at FROM training_checkpoints c JOIN training_sessions s ON s.id=c.session_id WHERE s.programme_id=?',[$pid])->fetchAll()).'<h3>Attendance events</h3>'.self::table(Database::query($this->p,'SELECT e.id,e.session_id,e.registration_id,e.action,e.happened_at,e.source FROM training_attendance_events e JOIN training_sessions s ON s.id=e.session_id WHERE s.programme_id=?',[$pid])->fetchAll()).'<h3>Correction requests</h3>'.self::table(Database::query($this->p,'SELECT c.id,c.event_id,c.proposed_at,c.reason,c.status FROM training_attendance_corrections c JOIN training_attendance_events e ON e.id=c.event_id JOIN training_sessions s ON s.id=e.session_id WHERE s.programme_id=?',[$pid])->fetchAll());
  if(Policy::allowed($this->p,$u,'cpd.manage',$r))$h.='<h3>CPD rule versions</h3>'.self::table(Database::query($this->p,'SELECT id,version,status FROM training_cpd_rules WHERE programme_id=?',[$pid])->fetchAll()).'<h3>CPD master data</h3>'.self::table(Database::query($this->p,"SELECT id,category,name FROM master_data WHERE category IN ('profession','regulator') AND is_active=1")->fetchAll());
  if(Policy::allowed($this->p,$u,'evaluations.manage',$r))$h.='<h3>Evaluation forms</h3>'.self::table(Database::query($this->p,'SELECT id,title,kind,published FROM training_evaluations WHERE programme_id=?',[$pid])->fetchAll());
  $this->page($h);
 }
}
